 function validChileanRut(value:string){const raw=value.replace(/[^0-9kK]/g,"").toUpperCase();if(raw.length<2)return false;const body=raw.slice(0,-1);const dv=raw.slice(-1);if(!/^\d+$/.test(body))return false;let sum=0,mult=2;for(let i=body.length-1;i>=0;i--){sum+=Number(body[i])*mult;mult=mult===7?2:mult+1;}const rem=11-(sum%11);const expected=rem===11?"0":rem===10?"K":String(rem);return dv===expected;}
